/* * @lc app=leetcode id=1896 lang=kotlin * * [1896] Minimum Cost to Change the Final Value of Expression */ class Solution { fun minOperationsToFlip(expression: String): Int = mutableListOf<Char>().let { ops -> mutableListOf<Pair<Int, Int>>().let { vals -> object { fun step() = ops.removeAt(ops.size - 1).let { op -> vals.removeAt(vals.size - 1).let { b -> vals.removeAt(vals.size - 1).let { a -> vals.add(if (op == '&') { if (a.first == 0 && b.first == 0) 0 to minOf(a.second, b.second) + 1 else if (a.first == 1 && b.first == 1) 1 to minOf(a.second, b.second) else 0 to 1 } else { if (a.first == 0 && b.first == 0) 0 to minOf(a.second, b.second) else if (a.first == 1 && b.first == 1) 1 to minOf(a.second, b.second) + 1 else 1 to 1 }) } } } fun runWhile() { if (ops.isNotEmpty() && ops.last() != '(') step().let { runWhile() } } fun runAll() { if (ops.isNotEmpty()) step().let { runAll() } } }.let { ev -> expression.forEach { c -> when (c) { '(' -> {ops.add(c)} ')' -> {ev.runWhile().let { ops.removeAt(ops.size - 1) }} '&', '|' -> {ev.runWhile().let { ops.add(c) }} '0' -> {vals.add(0 to 1)} '1' -> vals.add(1 to 1) } }.let { ev.runAll() }.let { vals.last().second } } } }}